56	\State $\mathcal{M}' \gets \text{GRPO}(\mathcal{M}_\text{warm}, \mathcal{D}_\text{rlvr})$ \hfill $\triangleright$ recover reasoning
57	\State \Return $\mathcal{M}'$
58	\end{algorithmic}
59	\end{algorithm}
